import{_ as t,a as i,b as r}from"./chunks/ai-create-03.Cig2rYP0.js";import{_ as e,o,c as n,a3 as l}from"./chunks/framework.D1iekJsc.js";const _=JSON.parse('{"title":"AI 创建角色","description":"MiniTavern 用已配置的模型写一段描述、可选参考图，生成角色卡；预览里可改字段、保留后再创建。","frontmatter":{"title":"AI 创建角色","description":"MiniTavern 用已配置的模型写一段描述、可选参考图，生成角色卡；预览里可改字段、保留后再创建。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"AI 创建角色 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern 用已配置的模型写一段描述、可选参考图，生成角色卡；预览里可改字段、保留后再创建。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/manual/ai-create"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/manual/ai-create"}]]},"headers":[],"relativePath":"manual/ai-create.md","filePath":"manual/ai-create.md","lastUpdated":1791861929000}'),s={name:"manual/ai-create.md"};function c(g,a,p,h,d,m){return o(),n("div",null,[...a[0]||(a[0]=[l('<h1 id="ai-创建角色" tabindex="-1">AI 创建角色 <a class="header-anchor" href="#ai-创建角色" aria-label="Permalink to &quot;AI 创建角色&quot;">​</a></h1><p>路径：底部 <strong>角色卡</strong> → <strong>创建 / 导入</strong> → <strong>AI 创建</strong>。</p><p>先配好一条 <a href="./model-link">模型连接</a> 并测连成功。没有可用模型时不能生成，页面会引导去配置。</p><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><div class="shot-flow"><figure class="shot-step"><img src="'+t+'" alt="AI 创建入口"><figcaption>1 · 创建 / 导入 → AI 创建</figcaption></figure><figure class="shot-step"><img src="'+i+'" alt="填写描述和参考图"><figcaption>2 · 选模型、写描述</figcaption></figure><figure class="shot-step"><img src="'+r+'" alt="预览并创建角色"><figcaption>3 · 预览后创建角色</figcaption></figure></div><h2 id="生成" tabindex="-1">生成 <a class="header-anchor" href="#生成" aria-label="Permalink to &quot;生成&quot;">​</a></h2><ol><li><strong>生成模型</strong>：从已经配置好的模型连接里选一个。默认是设为默认的那条，也可以改选其它连接。</li><li><strong>描述</strong>（必填）：用一段话说明想要的角色。</li><li><strong>参考图</strong>（可选）：点图片可以放大查看，右上角关闭图标可以去掉。有图时，所选模型必须支持图片；不支持则换模型或去掉图。</li><li>点 <strong>生成</strong>。按钮会显示「生成中」，这时不能再改模型、描述和参考图。</li></ol><p>参考图用来让模型看人设。第一次生成成功后，这张图会预填成 <strong>角色头像</strong>；模型不会另外画一张新图。没传参考图时，预览里要自己选一张头像才能创建。</p><p>生成失败会弹出说明，点「查看详情」可看原因。取消生成不会弹出失败说明。</p><h2 id="预览与保留" tabindex="-1">预览与保留 <a class="header-anchor" href="#预览与保留" aria-label="Permalink to &quot;预览与保留&quot;">​</a></h2><p>生成成功后进入 <strong>预览角色卡</strong>。生成页本身不展示角色数据。</p><ul><li>名称、描述、标签、性格、开场白、世界书等都可以直接改。</li><li>每个 AI 字段旁，以及整本 <strong>世界书</strong>，都有 <strong>保留</strong>。打开后，下次重新生成不会覆盖这一项。手改文字不会自动打开保留。</li><li>点 <strong>重新生成</strong> 会先弹出输入框。可以写想改的地方；留空则按原来的描述再生成。已打开「保留」的字段和世界书不动。全部都保留时不会再发请求。</li><li>生成过程中，「重新生成」显示加载，「创建角色」变成取消。</li><li>点 <strong>创建角色</strong> 时会有加载提示，完成后提示已创建。创建前必须有头像、名称和描述。</li><li>以动漫、影视等已有作品为原型时，结果里可以带上一本世界书。创建后卡内会保留这份设定，并复制成一本可在聊天里使用的世界书。用法见 <a href="./lorebook">世界书</a>。</li><li>还没创建就离开预览，会丢掉这次草稿，回到生成页。参考图仍留在生成页。</li></ul><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./chara-card">角色卡</a>：导入、编辑、开聊</li><li><a href="./model-link">模型连接</a>：先配好用来生成的模型</li></ul>',14)])])}const A=e(s,[["render",c]]);export{_ as __pageData,A as default};
